#define REPEAT_LIBRARY
#include "repeat.cpp"
vector<vector<D>> dr;
// Min(DTD0, path to a four-ply cycle + 8). Only positions with DTD0>8 can improve.
void solve4(int id){auto&t=ts[id];auto&v=dr[id];v=ds[id];vector<vector<U>> buckets(128);auto push=[&](U a,int k){if(k>=v[a])return;v[a]=k;assert(k<128);buckets[k].push_back(a);};long long high=0,direct=0;for(U a=0;a<(U)t.sz;a++){if(t.v[a]!=0||v[a]<=8)continue;high++;Pos p=dec(t,a);if(four(id,p)){push(a,8);direct++;continue;}int best=v[a];moves(t,p,[&](Move m,Pos x){if(m.cap<0&&!m.pr)return;auto[j,q]=child(t,p,m,x);U b=enc(ts[j],q);if(pc(ts[j].v[b])==0&&dr[j][b]!=INF)best=min(best,int(dr[j][b])+1);},true);if(best<v[a])push(a,best);}
for(int k=8;k<128;k++)for(U a:buckets[k]){if(v[a]!=k)continue;Pos p=dec(t,a);preds(t,p,[&](U b){if(t.v[b]==0)push(b,k+1);});}
long long improved=0,exact=0,un=0,inf=0;map<int,long long> h;ofstream f("rep4_"+t.name+".bin",ios::binary);f.write((char*)v.data(),2ull*v.size());for(U a=0;a<(U)t.sz;a++)if(pc(t.v[a])==0){if(v[a]<ds[id][a])improved++;if(v[a]<=12)exact++;else un++;if(v[a]==INF)inf++;h[v[a]]++;}lock_guard<mutex>lk(outmu);ofstream o("repeat_dp_stats.tsv",ios::app);o<<t.name<<'\t'<<high<<'\t'<<direct<<'\t'<<improved<<'\t'<<exact<<'\t'<<un<<'\t'<<inf<<'\n';ofstream hh("repeat_dp_hist.tsv",ios::app);for(auto[k,n]:h)hh<<t.name<<'\t'<<k<<'\t'<<n<<'\n';cerr<<t.name<<" high "<<high<<" direct "<<direct<<" improved "<<improved<<" exact "<<exact<<" unresolved "<<un<<" inf "<<inf<<endl;}
int main(){init();setup();load();loadD();dr.resize(ts.size());remove("repeat_dp_stats.tsv");remove("repeat_dp_hist.tsv");for(int i=0;i<6;i++)solve4(i);for(int np=0;np<=2;np++){vector<int> jobs;for(int i=6;i<(int)ts.size();i++)if((ts[i].t[2]==P)+(ts[i].t[3]==P)==np)jobs.push_back(i);atomic<int> j{0};vector<thread> th;for(int w=0;w<3;w++)th.emplace_back([&]{for(;;){int x=j++;if(x>=jobs.size())break;solve4(jobs[x]);}});for(auto&x:th)x.join();}}
